"""시험용 합성 TRC. 실제 차량 파일(VIN 포함)은 저장소에 넣지 않는다."""

TRC_HEADER = """;$FILEVERSION=1.1
;$STARTTIME=46301.0
;
;   Start time: 10/6/2026 10:00:00.000.0
;   Generated by PCAN-View v6.1.0.1056
;---+--   ----+----  --+--  ----+---  +  -+ -- -- -- -- -- -- --
"""


def isotp_frames(payload: bytes) -> list[bytes]:
    if len(payload) <= 7:
        return [bytes([len(payload)]) + payload + b"\xAA" * (7 - len(payload))]
    frames = [bytes([0x10 | (len(payload) >> 8), len(payload) & 0xFF]) + payload[:6]]
    rest, sn = payload[6:], 1
    while rest:
        chunk, rest = rest[:7], rest[7:]
        frames.append(bytes([0x20 | sn]) + chunk + b"\xAA" * (7 - len(chunk)))
        sn = (sn + 1) % 16
    return frames


def exchange(request_id: int, request: bytes, response: bytes, response_id: int | None = None):
    """요청 하나와 응답(다중 프레임이면 흐름제어 포함) 프레임 목록."""
    response_id = response_id or request_id + 8
    out = [(request_id, isotp_frames(request)[0])]
    frames = isotp_frames(response)
    out.append((response_id, frames[0]))
    if len(frames) > 1:
        out.append((request_id, bytes([0x30, 0, 2, 0, 0, 0, 0, 0])))
        out.extend((response_id, frame) for frame in frames[1:])
    return out


def trc(frames: list[tuple[int, bytes]], start_ms: float = 1000.0, step_ms: float = 10.0) -> str:
    lines = [TRC_HEADER.rstrip("\n")]
    for number, (can_id, data) in enumerate(frames, 1):
        hex_data = " ".join(f"{b:02X}" for b in data)
        lines.append(f"{number:6d}) {start_ms + number * step_ms:11.1f}  Rx         {can_id:04X}  "
                     f"{len(data)}  {hex_data} ")
    return "\n".join(lines) + "\n"


def bms_0101(soc=94.5, current=-12.3, voltage=785.5, max_temp=24, min_temp=23, cell_max=4.08,
             cell_min=4.06, cum_ah=1756.5) -> bytes:
    """62 01 01 응답. 바이트 배치는 실제 데이터에서 확인한 것과 같게 만든다."""
    data = bytearray(59)
    data[4] = round(soc * 2)
    data[10:12] = round(current * 10).to_bytes(2, "big", signed=True)
    data[12:14] = round(voltage * 10).to_bytes(2, "big")
    data[14] = max_temp & 0xFF
    data[15] = min_temp & 0xFF
    data[23] = round(cell_max * 50)
    data[24] = 7
    data[25] = round(cell_min * 50)
    data[26] = 41
    data[29] = 144
    data[30:34] = round(cum_ah * 10).to_bytes(4, "big")
    return bytes([0x62, 0x01, 0x01]) + bytes(data)


def bms_session(count: int = 3, **values) -> str:
    frames = []
    for index in range(count):
        frames += exchange(0x7E4, b"\x22\x01\x01", bms_0101(soc=94.5 + index * 0.5, **values))
    frames += exchange(0x7E4, b"\x22\x01\x0A", b"\x7F\x22\x31")
    frames += exchange(0x7E4, b"\x19\x02\x08", b"\x59\x02\xFF\x0A\x7F\x00\x09")
    frames += exchange(0x7E2, b"\x22\xF1\x90", b"\x62\xF1\x90" + b"TESTVIN0000123456")
    return trc(frames)
